DROP TABLE IF EXISTS `account_book`;

CREATE TABLE `account_book` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `company_name` varchar(200) NOT NULL DEFAULT '' COMMENT '公司名称',
  `unified_social_credit_code` varchar(50) NOT NULL DEFAULT '' COMMENT '统一社会信用代码',
  `industry_id` int NOT NULL DEFAULT '0' COMMENT '行业代码id（取数据字典）',
  `value_added_tax_cate` tinyint NOT NULL DEFAULT '0' COMMENT '增值税种类[0：小规模纳税人；1：一般纳税人]',
  `enable_voucher_verify` tinyint(1) NOT NULL DEFAULT '0' COMMENT '凭证是否审核[0：不审核；1：审核]',
  `start_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '账套启用年月',
  `accounting_standard` tinyint NOT NULL DEFAULT '0' COMMENT '会计准则[0：小企业会计准则；1：企业会计准则；2：民间非盈利组织会计制度；3：农民专业合作社财务会计制度]',
  `enable_fixed_assets` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否启用固定资产模块[0：不启用；1：启用]',
  `enable_capital` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否启用资金模块[0：不启用；1：启用]',
  `enable_psi` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否启用进销存[0：不启用；1：启用]',
  `disable` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否禁用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  `member_id` bigint NOT NULL DEFAULT '0' COMMENT '用户id',
  `update_member_id` bigint NOT NULL DEFAULT '0' COMMENT '修改用户id',
  `del_flag` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除，0：删除，1：未删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户id',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='账套';

