DROP TABLE IF EXISTS `assist_calculate_customer`;

CREATE TABLE `assist_calculate_customer` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `customer_cate` varchar(200) NOT NULL DEFAULT '' COMMENT '客户类别',
  `address` varchar(200) NOT NULL DEFAULT '' COMMENT '详细地址',
  `contacts` varchar(50) NOT NULL DEFAULT '' COMMENT '联系人',
  `phone` varchar(20) NOT NULL DEFAULT '' COMMENT '手机',
  `disable` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否禁用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  `member_id` bigint NOT NULL DEFAULT '0' COMMENT '用户id',
  `update_member_id` bigint NOT NULL DEFAULT '0' COMMENT '修改用户id',
  `del_flag` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除，0：删除，1：未删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户id',
  `unified_social_credit_code` varchar(50) NOT NULL DEFAULT '' COMMENT '统一社会信用代码',
  `province_code` varchar(50) NOT NULL DEFAULT '' COMMENT '省份编码',
  `city_code` varchar(50) NOT NULL DEFAULT '' COMMENT '城市编码',
  `county_code` varchar(50) NOT NULL DEFAULT '' COMMENT '县级编码',
  `assist_calculate_summary_id` bigint NOT NULL DEFAULT '0' COMMENT '辅助核算id',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='辅助核算客户表';

