DROP TABLE IF EXISTS `currency_config`;

CREATE TABLE `currency_config` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `code` varchar(10) NOT NULL DEFAULT '' COMMENT '编码[RMB，USD]',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '币别名称[人民币，美元]',
  `exchange_rate` decimal(10,4) NOT NULL COMMENT '汇率',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户id',
  `disable` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否禁用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  `member_id` bigint NOT NULL DEFAULT '0' COMMENT '用户id',
  `update_member_id` bigint NOT NULL DEFAULT '0' COMMENT '修改用户id',
  `del_flag` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除，0：删除，1：未删除',
  `base_currency_flag` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否是本位币，0：否，1：是',
  `use_count` int NOT NULL DEFAULT '0' COMMENT '使用计数',
  PRIMARY KEY (`id`),
  UNIQUE KEY `currency_config_tenant_id_code_uindex` (`tenant_id`,`code`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='货币配置';

