  `del_flag` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除，0：删除，1：未删除',
  PRIMARY KEY (`id`),
  KEY `file_ref_mapping_ref_type_ref_id_index` (`ref_type`,`ref_id`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='文件引用映射表';

