DROP TABLE IF EXISTS `member`;

CREATE TABLE `member` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `nick_name` varchar(50) NOT NULL DEFAULT '' COMMENT '用户昵称',
  `disable` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否禁用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '姓名',
  `avatar_url` varchar(200) NOT NULL DEFAULT '' COMMENT '头像',
  `sys_role_ids` json NOT NULL COMMENT '角色id，多个以英文逗号分隔',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户id',
  `email` varchar(50) NOT NULL DEFAULT '' COMMENT '邮箱地址',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户表';

