DROP TABLE IF EXISTS `mq_msg`;

CREATE TABLE `mq_msg` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `msg` json NOT NULL COMMENT '消息内容 json格式',
  `mq_topic` varchar(50) NOT NULL COMMENT '消息topic',
  `mq_tag` varchar(50) NOT NULL COMMENT '消息tag',
  `mq_key` varchar(50) NOT NULL COMMENT '消息key',
  `msg_class_name` varchar(200) NOT NULL DEFAULT '' COMMENT '消息类型类名称',
  `msg_status` tinyint NOT NULL DEFAULT '0' COMMENT '事件状态[0:未处理 1:处理成功 2:处理失败]',
  `error_count` int NOT NULL DEFAULT '0' COMMENT '错误次数',
  `error_msg` varchar(200) NOT NULL DEFAULT '' COMMENT '错误消息',
  `request_id` varchar(90) NOT NULL DEFAULT '' COMMENT '消息唯一编码,请求id，幂等性处理',
  `disable` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否禁用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  `member_id` bigint NOT NULL DEFAULT '0' COMMENT '用户id',
  `update_member_id` bigint NOT NULL DEFAULT '0' COMMENT '修改用户id',
  `del_flag` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除，0：删除，1：未删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户id',
  `data_no` varchar(50) NOT NULL DEFAULT '' COMMENT '数据编号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `mq_msg_request_id_uindex` (`request_id`)
) ENGINE=InnoDB AUTO_INCREMENT=34 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='mq消息';

