DROP TABLE IF EXISTS `report_formula`;

CREATE TABLE `report_formula` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `report_type` varchar(50) NOT NULL COMMENT '报表类型，资产负债表，利润表，现金流表等等',
  `report_formula` json NOT NULL COMMENT '报表公式，[{rowNo,subjectId:1,operationalSymbol:+,readDataRule:0}]  rowNo:行次，subjectId:科目id，operationalSymbol：操作符 ，readDataRule：取数规则',
  `account_book_id` bigint NOT NULL DEFAULT '0' COMMENT '账套id',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  `member_id` bigint NOT NULL DEFAULT '0' COMMENT '用户id',
  `update_member_id` bigint NOT NULL DEFAULT '0' COMMENT '修改用户id',
  `del_flag` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除，0：删除，1：未删除',
  `version` int NOT NULL DEFAULT '0' COMMENT '公式版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `report_formula_report_type_account_book_id_uindex` (`report_type`,`account_book_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='报表公式';

DROP TABLE IF EXISTS `subject`;

CREATE TABLE `subject` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `pid` bigint NOT NULL DEFAULT '0' COMMENT '父类id',
  `code` varchar(50) NOT NULL DEFAULT '' COMMENT '科目编码',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '科目名称',
  `mnemonic_code` varchar(50) NOT NULL DEFAULT '' COMMENT '助记码',
  `balance_direction` tinyint NOT NULL DEFAULT '0' COMMENT '余额方向[1：借，2：贷]',
  `level` int NOT NULL DEFAULT '0' COMMENT '科目层级',
  `calculate_config` json NOT NULL COMMENT '核算配置[数量核算，辅助核算，外币核算]',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户id',
  `disable` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否禁用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  `member_id` bigint NOT NULL DEFAULT '0' COMMENT '用户id',
  `update_member_id` bigint NOT NULL DEFAULT '0' COMMENT '修改用户id',
  `del_flag` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除，0：删除，1：未删除',
  `subject_cate` int NOT NULL DEFAULT '0' COMMENT '科目类别：1：资产，2：负债，3：权益，4：成本，5：损益',
  `node_depth` int NOT NULL DEFAULT '0' COMMENT '节点深度',
  `depth_code_length_one` int NOT NULL DEFAULT '0' COMMENT '一级节点编码长度',
  `depth_code_length_two` int NOT NULL DEFAULT '0' COMMENT '二级节点编码长度',
  `depth_code_length_three` int NOT NULL DEFAULT '0' COMMENT '三级编码长度',
  `depth_code_length_four` int NOT NULL DEFAULT '0' COMMENT '四级编码长度',
  `subject_type` tinyint NOT NULL DEFAULT '0' COMMENT '科目类型[0：系统科目，不能删除，1：自定义科目，可自行删除]',
  `use_count` int NOT NULL DEFAULT '0' COMMENT '使用计数',
  `parent_subject_disable` tinyint(1) NOT NULL DEFAULT '0' COMMENT '上级科目禁用启用状态',
  `pid_path` varchar(250) NOT NULL DEFAULT '' COMMENT '父节点全路径，比如/1/2/3',
  PRIMARY KEY (`id`),
  UNIQUE KEY `subject_tenant_id_code_uindex` (`tenant_id`,`code`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='科目';

