DROP TABLE IF EXISTS `sys_menu`;

CREATE TABLE `sys_menu` (
  `id` int NOT NULL AUTO_INCREMENT,
  `pid` int NOT NULL DEFAULT '0' COMMENT '父级菜单',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '菜单名称',
  `path` varchar(200) NOT NULL DEFAULT '' COMMENT '菜单路由',
  `component` varchar(200) NOT NULL DEFAULT '' COMMENT '菜单组件',
  `icon` varchar(20) NOT NULL DEFAULT '' COMMENT '图标',
  `layout` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否使用布局',
  `hide_in_menu` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否隐藏菜单',
  `redirect` varchar(200) NOT NULL DEFAULT '' COMMENT '重定向地址',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  `member_id` bigint NOT NULL DEFAULT '0' COMMENT '用户id',
  `update_member_id` bigint NOT NULL DEFAULT '0' COMMENT '修改用户id',
  `del_flag` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除，0：删除，1：未删除',
  `disable` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否禁用',
  `node_path` int NOT NULL DEFAULT '0' COMMENT '节点深度，0表示一级节点',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='系统菜单';

