DROP TABLE IF EXISTS `sys_resource`;

CREATE TABLE `sys_resource` (
  `id` int NOT NULL AUTO_INCREMENT,
  `pid` int NOT NULL DEFAULT '0' COMMENT '父id',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '资源名称',
  `path` varchar(200) NOT NULL DEFAULT '' COMMENT '资源路径',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  `member_id` bigint NOT NULL DEFAULT '0' COMMENT '用户id',
  `update_member_id` bigint NOT NULL DEFAULT '0' COMMENT '修改用户id',
  `del_flag` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除，0：删除，1：未删除',
  `disable` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否禁用',
  `node_path` int NOT NULL DEFAULT '0' COMMENT '节点深度',
  PRIMARY KEY (`id`),
  UNIQUE KEY `sys_resource_path_uindex` (`path`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='系统资源';

