DROP TABLE IF EXISTS `tenant_sys_config`;

CREATE TABLE `tenant_sys_config` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `config_name` varchar(200) NOT NULL DEFAULT '' COMMENT '配置名称',
  `config_key` varchar(50) NOT NULL DEFAULT '' COMMENT '配置key',
  `config_value` json NOT NULL COMMENT '配置内容',
  `disable` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否禁用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  `member_id` bigint NOT NULL DEFAULT '0' COMMENT '用户id',
  `update_member_id` bigint NOT NULL DEFAULT '0' COMMENT '修改用户id',
  `del_flag` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除，0：删除，1：未删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户id',
  PRIMARY KEY (`id`),
  UNIQUE KEY `tenant_sys_config_tenant_id_config_key_uindex` (`tenant_id`,`config_key`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='租户系统配置';

INSERT INTO `bage-finance-local`.`tenant_sys_config` (`id`, `config_name`, `config_key`, `config_value`, `disable`, `create_time`, `update_time`, `member_id`, `update_member_id`, `del_flag`, `tenant_id`) VALUES ('1', '科目编码长度配置', 'subject_code_length_config', '{"depthCodeLengthOne": 4, "depthCodeLengthTwo": 3, "depthCodeLengthFour": 2, "depthCodeLengthThree": 2}', '0', '2023-10-28 02:32:00', '2023-10-28 02:32:00', '0', '0', '0', '6');

DROP TABLE IF EXISTS `voucher`;

CREATE TABLE `voucher` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `voucher_word_config_id` bigint NOT NULL DEFAULT '0' COMMENT '凭证字配置id',
  `voucher_number` int NOT NULL DEFAULT '0' COMMENT '凭证号',
  `voucher_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '凭证日期',
  `document_num` int NOT NULL DEFAULT '0' COMMENT '单据数量',
  `total_amount` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '凭证总金额',
  `notes` varchar(250) NOT NULL DEFAULT '' COMMENT '备注',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户id',
  `disable` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否禁用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  `member_id` bigint NOT NULL DEFAULT '0' COMMENT '用户id',
  `update_member_id` bigint NOT NULL DEFAULT '0' COMMENT '修改用户id',
  `del_flag` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除，0：删除，1：未删除',
  `version` int NOT NULL DEFAULT '0' COMMENT '凭证版本',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='凭证表';

