DROP TABLE IF EXISTS `voucher_subject_assist_calculate_detail`;

CREATE TABLE `voucher_subject_assist_calculate_detail` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `voucher_id` bigint NOT NULL DEFAULT '0' COMMENT '凭证id',
  `subject_id` bigint NOT NULL DEFAULT '0' COMMENT '科目id',
  `voucher_subject_detail_id` bigint NOT NULL DEFAULT '0' COMMENT '凭证科目明细id',
  `assist_calculate_cate_id` bigint NOT NULL DEFAULT '0' COMMENT '辅助核算类别id',
  `assist_calculate_cate_code` varchar(50) NOT NULL DEFAULT '' COMMENT '辅助核算类别编码',
  `assist_calculate_id` bigint NOT NULL DEFAULT '0' COMMENT '辅助核算id',
  `assist_calculate_code` varchar(50) NOT NULL DEFAULT '' COMMENT '辅助核算编码',
  `assist_calculate_name` bigint NOT NULL DEFAULT '0' COMMENT '辅助核算名称',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户id',
  `disable` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否禁用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  `member_id` bigint NOT NULL DEFAULT '0' COMMENT '用户id',
  `update_member_id` bigint NOT NULL DEFAULT '0' COMMENT '修改用户id',
  `del_flag` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除，0：删除，1：未删除',
  `row_no` int NOT NULL DEFAULT '0' COMMENT '第几行数据，行编号',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='凭证辅科目辅助核算明细表';

