DROP TABLE IF EXISTS `voucher_subject_detail`;

CREATE TABLE `voucher_subject_detail` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `voucher_id` bigint NOT NULL DEFAULT '0' COMMENT '凭证id',
  `subject_id` bigint NOT NULL DEFAULT '0' COMMENT '科目id',
  `currency_config_id` bigint NOT NULL DEFAULT '0' COMMENT '币别id，如果未启用外币辅助核算则为0',
  `exchange_rate` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '汇率',
  `original_currency` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '原币',
  `subject_num` int NOT NULL DEFAULT '0' COMMENT '科目对应的数量',
  `subject_unit_price` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '科目对应的单价数量',
  `enable_foreign_currency_config` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否启用外币核算',
  `enable_number_calculate_config` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否启用数量核算',
  `enable_assist_calculate_configs` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否启用辅助核算',
  `balance` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '余额',
  `debit_amount` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '借方金额',
  `credit_amount` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '贷方金额',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户id',
  `disable` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否禁用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  `member_id` bigint NOT NULL DEFAULT '0' COMMENT '用户id',
  `update_member_id` bigint NOT NULL DEFAULT '0' COMMENT '修改用户id',
  `del_flag` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除，0：删除，1：未删除',
  `summary` varchar(250) NOT NULL DEFAULT '' COMMENT '摘要',
  `row_no` int NOT NULL DEFAULT '0' COMMENT '第几行数据，行编号',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=57 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='凭证科目明细表';

INSERT INTO `bage-finance-local`.`voucher_subject_detail` (`id`, `voucher_id`, `subject_id`, `currency_config_id`, `exchange_rate`, `original_currency`, `subject_num`, `subject_unit_price`, `enable_foreign_currency_config`, `enable_number_calculate_config`, `enable_assist_calculate_configs`, `balance`, `debit_amount`, `credit_amount`, `tenant_id`, `disable`, `create_time`, `update_time`, `member_id`, `update_member_id`, `del_flag`, `summary`, `row_no`) VALUES ('5', '6', '1', '0', '0.00', '0.00', '1', '1.00', '0', '1', '0', '0.00', '1.00', '0.00', '6', '0', '2024-04-08 02:47:44', '2024-04-08 12:35:58', '3', '0', '1', '1', '1');

