DROP TABLE IF EXISTS `voucher_word_config`;

CREATE TABLE `voucher_word_config` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `voucher_word` varchar(50) NOT NULL DEFAULT '' COMMENT '凭证纸字',
  `print_title` varchar(50) NOT NULL DEFAULT '' COMMENT '打印标题',
  `default_flag` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否是默认[0:否，1：默认]',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户id',
  `disable` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否禁用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  `member_id` bigint NOT NULL DEFAULT '0' COMMENT '用户id',
  `update_member_id` bigint NOT NULL DEFAULT '0' COMMENT '修改用户id',
  `del_flag` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除，0：删除，1：未删除',
  `use_count` int NOT NULL DEFAULT '0' COMMENT '使用计数',
  PRIMARY KEY (`id`),
  UNIQUE KEY `voucher_word_config_tenant_id_voucher_word_uindex` (`tenant_id`,`voucher_word`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='凭证字配置';

INSERT INTO `bage-finance-local`.`voucher_word_config` (`id`, `voucher_word`, `print_title`, `default_flag`, `tenant_id`, `disable`, `create_time`, `update_time`, `member_id`, `update_member_id`, `del_flag`, `use_count`) VALUES ('1', '记_del_1', '记账凭证', '0', '6', '0', '2024-03-07 11:24:01', '2024-03-07 11:40:04', '3', '3', '1', '0');

